#[test]
fn frozen_schema_literals_cover_closed_domain_and_refusals() {
    let mut tagged = 0;
    for case in CASES {
        if case.category == "expanded-tagged-variant" {
            tagged += 1;
        }
        let result = decode_case(case.type_name, case.raw);
        if let Err(
            DecodeError::Limits
            | DecodeError::SavedBytes
            | DecodeError::Work(_)
            | DecodeError::Allocation
            | DecodeError::Literal(
                crate::json::strict::StrictReadError::Work(_)
                | crate::json::strict::StrictReadError::Limits,
            ),
        ) = &result
        {
            panic!(
                "case {} exhausted test resources rather than validating its authored shape: {result:?}",
                case.id
            );
        }
        assert_eq!(
            result.is_ok(),
            case.accepts,
            "case {} type {} category {} literal {} result {result:?}",
            case.id,
            case.type_name,
            case.category,
            case.raw
        );
    }
    assert_eq!(tagged, 214);
}
